import { Firecrawl } from "@mendable/firecrawl-js";
import { GoogleGenAI } from "@google/genai";

interface Env {
  FIRECRAWL_API_KEY: string;
  GEMINI_API_KEY: string;
  AIG_TOKEN?: string;
  CF_ACCOUNT_ID: string;
  GATEWAY_ID: string;
  MODEL: string;
}

type Captured = { method: string; url: string; headers: Record<string, string>; body?: unknown; bodyBytes?: number };

const SECRET_HEADERS = new Set(["authorization", "x-goog-api-key", "cf-aig-authorization", "x-api-key"]);

const sha = async (bytes: Uint8Array) =>
  [...new Uint8Array(await crypto.subtle.digest("SHA-256", bytes))].map((b) => b.toString(16).padStart(2, "0")).join("").slice(0, 16);

// Records every outgoing request made while `fn` runs, with secrets and inline image data redacted.
const capture = async <T>(fn: () => Promise<T>): Promise<{ result?: T; error?: string; captured: Captured[] }> => {
  const original = globalThis.fetch;
  const captured: Captured[] = [];

  globalThis.fetch = (async (input: any, init?: any) => {
    const req = new Request(input, init);
    const headers: Record<string, string> = {};
    req.headers.forEach((v, k) => (headers[k] = SECRET_HEADERS.has(k) ? "<redacted>" : v));
    const entry: Captured = { method: req.method, url: req.url, headers };

    if (req.method !== "GET" && req.method !== "HEAD") {
      const buf = new Uint8Array(await req.clone().arrayBuffer());
      entry.bodyBytes = buf.length;
      const text = new TextDecoder().decode(buf);
      try {
        const json = JSON.parse(text);
        for (const c of json.contents ?? []) for (const p of c.parts ?? []) {
          if (p.inlineData) p.inlineData.data = `<${p.inlineData.data.length} b64 chars, sha256:${await sha(new TextEncoder().encode(p.inlineData.data))}>`;
        }
        entry.body = json;
      } catch {
        entry.body = text.slice(0, 500);
      }
    }
    captured.push(entry);
    return original(req);
  }) as typeof fetch;

  try {
    return { result: await fn(), captured };
  } catch (e: any) {
    return { error: `${e?.name}: ${e?.message}`.slice(0, 800), captured };
  } finally {
    globalThis.fetch = original;
  }
};

const IMAGE_PROMPT = (title: string, alt: string) => `You are describing an image from a technical article for someone listening to the article who cannot see it.

Write exactly ONE sentence naming what the image SHOWS.

Rules:
- Be specific, never categorical. Read a chart's axes and its trend, name a screenshot's on-screen elements and the action taken, describe a photo's subject and setting. Never write only "a chart", "a screenshot", or "a photo".
- Begin the sentence with the thing shown. Never begin with "This", "The image", "An image of", "A picture of", or any preamble, and never use the word "This" anywhere in the sentence.
- Describe only what is visibly there. Do not name any person, organization, company, brand, product, place, or region unless that exact name appears as written text inside the image.
- Do not state what the image means or its role in the article. One sentence of visible content, with no second sentence.

Article title: ${title || "(untitled)"}

The alt text below is often wrong, empty, or SEO filler; use it only where it matches what you see and ignore it otherwise.
Alt text: ${alt || "(none)"}`;

const SCHEMA = { type: "OBJECT", properties: { spoken: { type: "STRING" } }, required: ["spoken"] };

const b64 = (bytes: Uint8Array) => {
  let s = "";
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(s);
};

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const u = new URL(request.url);
    const json = (o: unknown) => Response.json(o);
    const t0 = Date.now();

    if (u.pathname === "/fc/sdk" || u.pathname === "/fc/fetch") {
      const target = u.searchParams.get("url")!;
      const out = await capture(async () => {
        if (u.pathname === "/fc/sdk") {
          const doc: any = await new Firecrawl({ apiKey: env.FIRECRAWL_API_KEY }).scrape(target, { formats: ["rawHtml", "markdown"], proxy: "auto" });
          return { rawHtmlLen: doc.rawHtml?.length, markdownLen: doc.markdown?.length, metadata: doc.metadata, keys: Object.keys(doc) };
        }
        const res = await fetch("https://api.firecrawl.dev/v2/scrape", {
          method: "POST",
          headers: { "content-type": "application/json", authorization: `Bearer ${env.FIRECRAWL_API_KEY}` },
          body: JSON.stringify({ url: target, formats: ["rawHtml", "markdown"], proxy: "auto" }),
        });
        const body: any = await res.json();
        return { status: res.status, success: body.success, rawHtmlLen: body.data?.rawHtml?.length, markdownLen: body.data?.markdown?.length, metadata: body.data?.metadata };
      });
      return json({ ms: Date.now() - t0, ...out });
    }

    if (u.pathname === "/gemini") {
      const mode = u.searchParams.get("mode") ?? "fetch"; // sdk | fetch
      const via = u.searchParams.get("via") ?? "gateway"; // gateway | direct
      const aigAuth = u.searchParams.get("aigauth") === "1";
      const imageUrl = u.searchParams.get("image")!;
      const title = u.searchParams.get("title") ?? "";
      const img = await fetch(imageUrl);
      const bytes = new Uint8Array(await img.arrayBuffer());
      const mime = u.searchParams.get("mime") ?? img.headers.get("content-type")!.split(";")[0];
      const base = via === "gateway"
        ? `https://gateway.ai.cloudflare.com/v1/${env.CF_ACCOUNT_ID}/${env.GATEWAY_ID}/google-ai-studio`
        : "https://generativelanguage.googleapis.com";
      const extra: Record<string, string> = aigAuth && env.AIG_TOKEN ? { "cf-aig-authorization": `Bearer ${env.AIG_TOKEN}` } : {};
      const prompt = IMAGE_PROMPT(title, "");

      const out = await capture(async () => {
        if (mode === "sdk") {
          const ai = new GoogleGenAI({ apiKey: env.GEMINI_API_KEY, httpOptions: { baseUrl: base, headers: extra } });
          const r = await ai.models.generateContent({
            model: env.MODEL,
            contents: [prompt, { inlineData: { data: b64(bytes), mimeType: mime } }] as any,
            config: { responseMimeType: "application/json", responseSchema: { type: "object", properties: { spoken: { type: "string" } }, required: ["spoken"] } as any },
          });
          return { text: r.text, usage: r.usageMetadata };
        }
        const res = await fetch(`${base}/v1beta/models/${env.MODEL}:generateContent`, {
          method: "POST",
          headers: { "content-type": "application/json", "x-goog-api-key": env.GEMINI_API_KEY, ...extra },
          body: JSON.stringify({
            contents: [{ parts: [{ text: prompt }, { inlineData: { data: b64(bytes), mimeType: mime } }], role: "user" }],
            generationConfig: { responseMimeType: "application/json", responseSchema: SCHEMA },
          }),
        });
        const text = await res.text();
        return { status: res.status, respHeaders: Object.fromEntries([...res.headers].filter(([k]) => k.startsWith("cf-aig") || k === "content-type")), text: text.slice(0, 1200) };
      });
      return json({ mode, via, mime, imageBytes: bytes.length, ms: Date.now() - t0, ...out });
    }

    return new Response("nagara-spike-fc-gemini");
  },
};
